// Case-context sidecar: the extra reference data the clinician sees alongside a case.
//
// Generated by scripts/build_case_context.py into case-context.generated.json, keyed by
// `case_id`. It is deliberately SEPARATE from demo-cases.generated.json: that file is
// overwritten by the upstream exporter, so anything added there would be lost on the next
// export. Nothing here is model output — sleep indices come from the session metrics CSV and
// the future-disease list is the recorded ground truth, so none of it can leak arm identity.

import raw from '@/data/case-context.generated.json'

export interface SleepIndex {
  [field: string]: number | null
}

// Why the patient is in the batch: the cohort sub-group they were sampled from (healthy = a
// sleep-issue stratum with no 6-y panel onset; risky = a disease-category stratum). INTERNAL —
// rendered only behind the arm-reveal switch.
export interface CaseSelection {
  cohortGroup: 'healthy' | 'risky'
  stratum: string // short_tst | high_ahi | low_n3 | circulatory | endocrine_metabolic | ...
}

export interface CaseContextEntry {
  sessionId: string
  sourceIndex: number
  sleepIndex: SleepIndex
  futureDiseaseGroundTruth: string[]
  selection?: CaseSelection // absent for pre-v12.1 sidecars
}

// Clinician-readable stratum names (the raw keys are internal selector labels).
const STRATUM_LABEL: Record<string, string> = {
  short_tst: 'short total sleep time',
  high_ahi: 'high AHI',
  low_n3: 'low N3 (deep) sleep',
  circulatory: 'circulatory system',
  endocrine_metabolic: 'endocrine / metabolic',
  mental: 'mental disorders',
  neurological: 'neurological',
  respiratory: 'respiratory',
}

// Header-safe one-liner: "healthy · short total sleep time" / "risky · circulatory system".
// Contains no condition name, so it can sit next to the demographics.
export function stratumLabel(stratum: string): string {
  return STRATUM_LABEL[stratum] ?? stratum.replace(/_/g, ' ')
}
export function selectionSummary(sel: CaseSelection): string {
  return `${sel.cohortGroup} · ${stratumLabel(sel.stratum)}`
}

interface CaseContextFile {
  categoryOrder: string[]
  sleepIndexFields: string[]
  diseaseCategoryByName: Record<string, string>
  cases: Record<string, CaseContextEntry>
}

const data = raw as CaseContextFile

export const CATEGORY_ORDER = data.categoryOrder
export const DISEASE_CATEGORY = data.diseaseCategoryByName

export function caseContext(caseId: string): CaseContextEntry | undefined {
  return data.cases[caseId]
}

// --- sleep-index presentation ---------------------------------------------- //
// Display metadata only — label, unit, decimal places. No thresholds and no
// normal/abnormal verdict: the metrics CSV ships raw values, and inventing severity
// cut-offs here would put an un-reviewed clinical constant in the UI. The clinician
// reads the numbers.

export interface SleepMetricSpec {
  field: string
  label: string
  unit: string
}

export interface SleepMetricGroup {
  title: string
  metrics: SleepMetricSpec[]
}

export const SLEEP_INDEX_GROUPS: SleepMetricGroup[] = [
  {
    title: 'Breathing & oxygenation',
    metrics: [
      { field: 'ahi', label: 'AHI', unit: 'events/h' },
      { field: 'odi', label: 'ODI', unit: 'events/h' },
      { field: 'rdi', label: 'RDI', unit: 'events/h' },
      { field: 'mean_spo2', label: 'Mean SpO₂', unit: '%' },
      { field: 'nadir_spo2', label: 'Nadir SpO₂', unit: '%' },
    ],
  },
  {
    title: 'Sleep continuity',
    metrics: [
      { field: 'tst_min', label: 'TST', unit: 'min' },
      { field: 'trt_min', label: 'Time in bed', unit: 'min' },
      { field: 'se', label: 'Sleep efficiency', unit: '%' },
      { field: 'sol_min', label: 'Sleep onset latency', unit: 'min' },
      { field: 'waso_min', label: 'WASO', unit: 'min' },
      { field: 'ari', label: 'Arousal index', unit: 'events/h' },
      { field: 'plmi', label: 'PLMI', unit: 'events/h' },
    ],
  },
  {
    title: 'Sleep architecture',
    metrics: [
      { field: 'n1_pct', label: 'N1', unit: '%' },
      { field: 'n2_pct', label: 'N2', unit: '%' },
      { field: 'n3_pct', label: 'N3', unit: '%' },
      { field: 'rem_pct', label: 'REM', unit: '%' },
    ],
  },
]

// One decimal everywhere. The CSV carries full float precision (75.17985611510791),
// which is noise at reading distance.
export function formatMetric(value: number): string {
  return value.toFixed(1)
}

// --- disease grouping ------------------------------------------------------- //

export interface ConditionGroup {
  category: string
  conditions: string[]
}

// Bucket a flat disease-name list into organ-system groups, in CATEGORY_ORDER.
// Order WITHIN a group follows the input, which is already phecode-sorted upstream.
// A name with no mapping is surfaced under its own heading rather than dropped —
// the generator already fails on unmapped names, so this only fires if the sidecar
// and the case file drift apart, and it must stay visible when it does.
export function groupByCategory(names: string[]): ConditionGroup[] {
  const buckets = new Map<string, string[]>()
  for (const name of names) {
    const category = DISEASE_CATEGORY[name] ?? 'Other Prior Diagnosed Diseases'
    const bucket = buckets.get(category)
    if (bucket) bucket.push(name)
    else buckets.set(category, [name])
  }
  const rank = (c: string) => {
    const i = CATEGORY_ORDER.indexOf(c)
    return i === -1 ? CATEGORY_ORDER.length : i
  }
  return [...buckets.entries()]
    .map(([category, conditions]) => ({ category, conditions }))
    .sort((a, b) => rank(a.category) - rank(b.category))
}
